#include <vector>
#include <unordered_map>
#include <algorithm>

class RangeFreqQuery {
private:
    std::unordered_map<int, std::vector<int>> pos;

public:
    RangeFreqQuery(std::vector<int>& arr) {
        for (int i = 0; i < static_cast<int>(arr.size()); ++i) {
            pos[arr[i]].push_back(i);
        }
    }

    int query(int left, int right, int value) {
        auto it = pos.find(value);
        if (it == pos.end()) return 0;
        const auto& indices = it->second;
        auto l = std::lower_bound(indices.begin(), indices.end(), left);
        auto r = std::upper_bound(indices.begin(), indices.end(), right);
        return std::distance(l, r);
    }
};

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

class RangeFreqQuery {
    private Map<Integer, List<Integer>> pos = new HashMap<>();

    public RangeFreqQuery(int[] arr) {
        for (int i = 0; i < arr.length; i++) {
            pos.computeIfAbsent(arr[i], k -> new ArrayList<>()).add(i);
        }
    }

    public int query(int left, int right, int value) {
        List<Integer> indices = pos.get(value);
        if (indices == null) return 0;
        int l = lowerBound(indices, left);
        int r = upperBound(indices, right);
        return r - l;
    }

    private int lowerBound(List<Integer> list, int target) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (list.get(mid) < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    private int upperBound(List<Integer> list, int target) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (list.get(mid) <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

