var RangeFreqQuery = function(arr) {
    this.pos = new Map();
    for (let i = 0; i < arr.length; i++) {
        const v = arr[i];
        if (!this.pos.has(v)) this.pos.set(v, []);
        this.pos.get(v).push(i);
    }
};

RangeFreqQuery.prototype.query = function(left, right, value) {
    const indices = this.pos.get(value);
    if (!indices) return 0;

    let lo = 0, hi = indices.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (indices[mid] < left) lo = mid + 1;
        else hi = mid;
    }
    const l = lo;

    lo = 0; hi = indices.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (indices[mid] <= right) lo = mid + 1;
        else hi = mid;
    }
    const r = lo;

    return r - l;
};
